<?php require "auth.php"; $other=(int)($_GET["id"]??$_POST["id"]??0);$s=$pdo->prepare("SELECT id,name FROM users WHERE id=?");$s->execute([$other]);$person=$s->fetch();if(!$person)die("User not found.");
if($_SERVER["REQUEST_METHOD"]==="POST" && trim($_POST["message"])!==""){$q=$pdo->prepare("INSERT INTO messages(sender_id,receiver_id,message) VALUES(?,?,?)");$q->execute([$me,$other,trim($_POST["message"])]);header("Location: message.php?id=".$other);exit;}
$q=$pdo->prepare("SELECT * FROM messages WHERE (sender_id=? AND receiver_id=?) OR (sender_id=? AND receiver_id=?) ORDER BY created_at");$q->execute([$me,$other,$other,$me]);$msgs=$q->fetchAll(); ?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Chat</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="style.css"></head><body><div class="container py-4" style="max-width:800px"><a href="dashboard.php">← Back</a><h3 class="mt-3">Chat with <?=htmlspecialchars($person["name"])?></h3><div class="card p-3 mb-3" style="min-height:350px"><?php foreach($msgs as $m):?><div class="mb-2 text-<?=($m["sender_id"]==$me?"end":"start")?>"><span class="badge bg-<?=($m["sender_id"]==$me?"danger":"secondary")?>"><?=htmlspecialchars($m["message"])?></span></div><?php endforeach;?></div><form method="post" class="input-group"><input type="hidden" name="id" value="<?=$other?>"><input class="form-control" name="message" placeholder="Write a message..." required><button class="btn btn-danger">Send</button></form></div></body></html>